	/** 
	 * jumpstart the process by instantiating2 Exposure
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		exposureId = ExposureService.getExposureInstance()
		.createExposure( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		ExposureService.getExposureInstance()
				.createExposure( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.exposureSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Exposure : " + successValue.getExposureId());
							  if (successValue.getExposureId().equals(exposureId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfExposureList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Exposure test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on exposure consumed")
					);
			subscriber.exposureSubscribe( exposureId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Exposure : " + successValue.getExposureId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfExposureList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on exposure for exposureId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Exposure. 
	 */
	protected Exposure read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Exposure" );

		Exposure entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Exposure with primary key" );
		msg.append( exposureId );
		
		ExposureFetchOneSummary fetchOneSummary = new ExposureFetchOneSummary( exposureId );

		try {
			entity = ExposureService.getExposureInstance().getExposure( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Exposure " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Exposure.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Exposure." );

		StringBuilder msg = new StringBuilder( "Failed to update a Exposure : " );        
		Exposure entity = read();
		UpdateExposureCommand command = generateUpdateCommand();
		command.setExposureId(entity.getExposureId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Exposure." );

			// for use later on...
			exposureId = entity.getExposureId();

			ExposureService proxy = ExposureService.getExposureInstance();  

			proxy.updateExposure( command ).get();

			LOGGER.info( "-- Successfully saved Exposure - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + exposureId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Exposure.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Exposure." );

		Exposure entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Exposure with id " + exposureId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Exposure with id " + exposureId );

			throw e;
		}

		try{
			ExposureService.getExposureInstance().delete( new DeleteExposureCommand( entity.getExposureId() ) ).get();
			LOGGER.info( "-- Successfully deleted Exposure with id " + exposureId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Exposure with id " + exposureId );

			throw e;
		}
	}

	/**
	 * get all Exposures.
	 */
	protected List<Exposure> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Exposures:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Exposure : " );        
		List<Exposure> collection  = new ArrayList<>();

		try {
			// call the static get method on the ExposureService
			collection = ExposureService.getExposureInstance().getAllExposure();
			assertNotNull( collection, "An Empty collection of Exposure was incorrectly returned.");
			
			// Now print out the values
			Exposure entity = null;            
			Iterator<Exposure> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getExposureId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

